import java.io.*;
import java.util.*;
public class G{
    public static void main(String[] args) {
        new G().start();
    }

    void start() {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        FastWriter out = new FastWriter(outputStream);
        Solver task = new Solver();
        task.process(1, in, out);
        out.close();
    }

    static class Solver {
        static class MinCostFlow{
            List<Edge>[] adj;
            Edge[][] matrix;
            int[] dist;
            int nodes, source, sink, flow;
            int cost;
            final int INF = Integer.MAX_VALUE / 100;

            class Edge{
                int to, cap, revIdx, w;
                Edge(int t, int c, int w, int r){to=t; cap=c; w=w; revIdx=r;}
            }

            MinCostFlow(int n, int src, int tgt){
                nodes=n; source=src; sink=tgt; flow=0; cost=0;
                adj=new ArrayList[nodes];
                for(int i=0;i<nodes;i++) adj[i]=new ArrayList<>();
            }

            void addEdge(int u,int v,int cap,int w){
                int su=adj[u].size(),sv=adj[v].size();
                adj[u].add(new Edge(v,cap,w,sv));
                adj[v].add(new Edge(u,0,-w,su));
            }

            void buildMatrix(){
                matrix=new Edge[nodes][];
                for(int i=0;i<nodes;i++){
                    matrix[i]=adj[i].toArray(new Edge[0]);
                    adj[i].clear();
                }
            }

            boolean shortestPath(boolean detectNeg){
                Arrays.fill(dist,INF); dist[source]=0;
                for(int iter=0;iter<nodes-1;iter++){
                    for(int u=0;u<nodes;u++){
                        if(dist[u]==INF) continue;
                        for(Edge e:matrix[u]){
                            if(e.cap>0 && dist[u]+e.w<dist[e.to])
                                dist[e.to]=dist[u]+e.w;
                        }
                    }
                }
                if(detectNeg){
                    for(int u=0;u<nodes;u++){
                        if(dist[u]==INF) continue;
                        for(Edge e:matrix[u]){
                            if(e.cap>0 && dist[u]+e.w<dist[e.to]) return false;
                        }
                    }
                }
                return true;
            }

            int[] pnode,pedge,vis,distQ;
            int[] q;

            boolean spfa(){
                pnode=new int[nodes]; pedge=new int[nodes];
                vis=new int[nodes]; distQ=new int[nodes];
                q=new int[nodes];
                Arrays.fill(distQ,INF); distQ[source]=0;
                int head=0,tail=0;
                q[tail++]=source;
                while(head!=tail){
                    int u=q[head++]; if(head==nodes)head=0;
                    vis[u]=2;
                    for(int i=0;i<matrix[u].length;i++){
                        Edge e=matrix[u][i];
                        if(e.cap==0) continue;
                        int nd=distQ[u]+e.w;
                        if(nd<distQ[e.to]){
                            if(vis[e.to]==0){
                                q[tail++]=e.to; if(tail==nodes)tail=0;
                            }else if(vis[e.to]==2){
                                if(--head==-1)head+=nodes;
                                q[head]=e.to;
                            }
                            vis[e.to]=1;
                            pedge[e.to]=i; pnode[e.to]=u; distQ[e.to]=nd;
                        }
                    }
                }
                return vis[sink]!=0;
            }

            class P implements Comparable<P>{
                int node,dist;
                P(int n,int d){node=n;dist=d;}
                public int compareTo(P o){return Integer.compare(dist,o.dist);}
            }

            boolean dijkstraP(){
                Arrays.fill(vis,0); Arrays.fill(distQ,INF);
                pnode=new int[nodes]; pedge=new int[nodes];
                PriorityQueue<P> pq=new PriorityQueue<>();
                pq.add(new P(source,0)); distQ[source]=0;
                while(!pq.isEmpty()){
                    P cur=pq.poll();
                    while(distQ[cur.node]<cur.dist){
                        if(pq.isEmpty()) return false;
                        cur=pq.poll();
                    }
                    vis[cur.node]=2;
                    for(int i=0;i<matrix[cur.node].length;i++){
                        Edge e=matrix[cur.node][i];
                        if(e.cap==0) continue;
                        int rcost=e.w+dist[cur.node]-dist[e.to];
                        int nd=cur.dist+rcost;
                        if(nd<distQ[e.to]){
                            if(vis[e.to]==2) return false;
                            pq.add(new P(e.to,nd));
                            distQ[e.to]=nd; pnode[e.to]=cur.node; pedge[e.to]=i;
                            vis[e.to]=1;
                        }
                    }
                }
                return vis[sink]!=0;
            }

            int augmentFlow(){
                int pathCap=INF;
                int cur=sink;
                while(cur!=source){
                    int prev=pnode[cur],idx=pedge[cur];
                    pathCap=Math.min(pathCap,matrix[prev][idx].cap);
                    cur=prev;
                }
                cur=sink;
                while(cur!=source){
                    int prev=pnode[cur],idx=pedge[cur];
                    matrix[prev][idx].cap-=pathCap;
                    matrix[cur][matrix[prev][idx].revIdx].cap+=pathCap;
                    cur=prev;
                }
                flow+=pathCap;
                return pathCap;
            }

            void compute(){
                shortestPath(false);
                while(spfa()){
                    if(distQ[sink]>=INF-1) break;
                    cost+=distQ[sink]*augmentFlow();
                }
            }

            void computeWithPot(){
                shortestPath(false);
                while(dijkstraP()){
                    int m=distQ[sink]+dist[sink]-dist[source];
                    if(m>=INF-1) break;
                    cost+=m*augmentFlow();
                    for(int i=0;i<nodes;i++) if(vis[i]!=0) dist[i]+=distQ[i]-dist[source];
                }
            }
        }

        void process(int testNum,FastReader in,FastWriter out){
            int n=in.nextInt(),m=in.nextInt(),k=in.nextInt(),c=in.nextInt(),d=in.nextInt();
            int maxLen=n+k,dest=n*maxLen+1;
            MinCostFlow g=new MinCostFlow(dest+1,0,dest);
            int[] freq=new int[n+1], arr=new int[k+1];
            for(int i=1;i<=k;i++){
                arr[i]=in.nextInt();
                freq[arr[i]]++;
            }
            for(int i=1;i<=n;i++){
                if(freq[i]>0) g.addEdge(0,i,freq[i],0);
            }
            for(int i=2;i<=n;i++){
                for(int lvl=0;lvl<maxLen-1;lvl++){
                    g.addEdge(lvl*n+i,(lvl+1)*n+i,k,c);
                }
            }
            for(int i=1;i<=m;i++){
                int u=in.nextInt(),v=in.nextInt();
                for(int lvl=0;lvl<maxLen-1;lvl++){
                    for(int p=1;p<=k;p++){
                        if(u!=1) g.addEdge(n*lvl+u,n*(lvl+1)+v,1,d*(2*p-1)+c);
                        if(v!=1) g.addEdge(n*lvl+v,n*(lvl+1)+u,1,d*(2*p-1)+c);
                    }
                }
            }
            for(int lvl=1;lvl<maxLen;lvl++){
                g.addEdge(lvl*n+1,dest,k,0);
            }
            g.buildMatrix();
            g.computeWithPot();
            if(g.flow!=k) out.println("BUG");
            else out.println(g.cost);
        }
    }

    static class FastReader{
        BufferedReader br; StringTokenizer st;
        public FastReader(InputStream s){br=new BufferedReader(new InputStreamReader(s));st=null;}
        String next(){
            while(st==null||!st.hasMoreTokens()){
                String line=null;
                try{line=br.readLine();}catch(Exception e){}
                if(line==null)return null;
                st=new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt(){return Integer.parseInt(next());}
        long nextLong(){return Long.parseLong(next());}
    }

    static class FastWriter{
        PrintWriter pw;
        public FastWriter(OutputStream os){pw=new PrintWriter(os);}
        void println(Object o){pw.println(o);}
        void close(){pw.close();}
    }
}
